app.use(helmet());

// Or configure specific headers for more control
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"], // Only allow scripts from same origin
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
  frameguard: {
    action: 'deny', // Prevent clickjacking
  },
}));
```

---

### 2. **No Input Validation (OWASP A03: Injection)**

**Issue:** No validation on any incoming requests. While the current endpoints don't accept user input, this is a dangerous pattern.

**Risk:** If endpoints are added that accept user input without validation, injection attacks become possible.

**Recommendation:**

```javascript
const Joi = require('joi'); // or use express-validator

// Example: Validate future query parameters
const querySchema = Joi.object({
  page: Joi.number().integer().min(1).default(1),
  limit: Joi.number().integer().min(1).max(100).default(10),
});

app.get('/users', (req, res, next) => {
  const { error, value } = querySchema.validate(req.query);
  if (error) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: error.details[0].message 
    });
  }
  req.query = value;
  next();
});
```

---

### 3. **No Rate Limiting (OWASP A05: Security Misconfiguration)**

**Issue:** No protection against brute-force or DoS attacks.

**Risk:** Attackers can flood endpoints with requests, causing service disruption.

**Recommendation:**

```javascript
const rateLimit = require('express-rate-limit');

// General API rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: {
    error: 'Too many requests, please try again later.',
    retryAfter: '15 minutes'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Stricter limit for authentication endpoints
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 login attempts per 15 minutes
  skipSuccessfulRequests: true,
});

app.use('/api/', apiLimiter);
// app.use('/auth/login', loginLimiter);
```

---

### 4. **No CORS Configuration (OWASP A05: Security Misconfiguration)**

**Issue:** No Cross-Origin Resource Sharing (CORS) policy defined.

**Risk:** Unexpected cross-origin requests can access your API.

**Recommendation:**

```javascript
const cors = require('cors');

app.use(cors({
  origin: function(origin, callback) {
    // Whitelist allowed origins
    const allowedOrigins = ['https://trusted-domain.com', 'https://app.example.com'];

    // Allow requests with no origin (mobile apps, curl requests)
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST'], // Only allow needed methods
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // Cache preflight for 24 hours
}));
```

---

### 5. **No Request Size Limits (OWASP A05: Security Misconfiguration)**

**Issue:** No limit on request body size.

**Risk:** Client can send extremely large payloads causing memory exhaustion (DoS).

**Recommendation:**

```javascript
// Limit JSON body size to 10kb
app.use(express.json({ limit: '10kb' }));

// Limit URL-encoded body size  
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// For file uploads (if added later)
const multer = require('multer');
const upload = multer({ 
  limits: { fileSize: 5 * 1024 * 1024 } // 5MB limit
});
```

